@prefix cdifd: <https://cdif.org/validation/0.1/shacl#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode "dde:spatialRepresentationType" ;
            sh:resultMessage "schema:propertyID value looks like a URI or CURIE (prefix:localname) but is serialized as a string literal. Serialize URI values as JSON-LD IRI references: {\"@id\":\"...\"}. Free-label strings like 'temperature' remain valid as strings." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape cdifd:PropertyIDUriShouldBeIRIShape ;
            sh:value "dde:spatialRepresentationType" ],
        [ a sh:ValidationResult ;
            sh:focusNode "dde:referenceSystemType" ;
            sh:resultMessage "schema:propertyID value looks like a URI or CURIE (prefix:localname) but is serialized as a string literal. Serialize URI values as JSON-LD IRI references: {\"@id\":\"...\"}. Free-label strings like 'temperature' remain valid as strings." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape cdifd:PropertyIDUriShouldBeIRIShape ;
            sh:value "dde:referenceSystemType" ],
        [ a sh:ValidationResult ;
            sh:focusNode "dde:referenceSystemIdentifier" ;
            sh:resultMessage "schema:propertyID value looks like a URI or CURIE (prefix:localname) but is serialized as a string literal. Serialize URI values as JSON-LD IRI references: {\"@id\":\"...\"}. Free-label strings like 'temperature' remain valid as strings." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape cdifd:PropertyIDUriShouldBeIRIShape ;
            sh:value "dde:referenceSystemIdentifier" ],
        [ a sh:ValidationResult ;
            sh:focusNode "dde:spatialResolution" ;
            sh:resultMessage "schema:propertyID value looks like a URI or CURIE (prefix:localname) but is serialized as a string literal. Serialize URI values as JSON-LD IRI references: {\"@id\":\"...\"}. Free-label strings like 'temperature' remain valid as strings." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape cdifd:PropertyIDUriShouldBeIRIShape ;
            sh:value "dde:spatialResolution" ] .
